/* Slack DNA — aubergine primary, white surfaces, four-color accents, approachable */
.theme-slack-dna {
  --bg: oklch(0.99 0.002 300);
  --surface: oklch(1 0 0);
  --surface-2: oklch(0.96 0.008 320);
  --fg: oklch(0.24 0.04 320);
  --fg-muted: oklch(0.52 0.03 320);
  --accent: oklch(0.306 0.108 327.1);
  --accent-fg: oklch(1 0 0);
  --accent-2: oklch(0.768 0.130 223.2);
  --line: oklch(0.88 0.01 320);
  --success: oklch(0.65 0.15 150);
  --warning: oklch(0.82 0.16 85);
  --danger: oklch(0.520 0.199 14.6);

  --radius: 0.5rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.75rem;
  --radius-pill: 9999px;

  --shadow-1: 0 1px 2px oklch(0.24 0.04 320 / 10%);
  --shadow-2: 0 4px 12px -4px oklch(0.24 0.04 320 / 18%);
  --shadow-3: 0 16px 40px -16px oklch(0.24 0.04 320 / 28%);
  --glow: 0 0 0 3px color-mix(in oklab, var(--accent-2) 40%, transparent);

  --border-width: 1px;
  --blur-amount: 0px;

  --font-display: "Lato", sans-serif;
  --font-body: "Lato", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --tracking-display: -0.02em;
  --label-transform: none;
  --label-tracking: 0.01em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-slack-dna h1,
.theme-slack-dna h2,
.theme-slack-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
  font-weight: 800;
}

/* Four-color accent system, rotated across repeated blocks */
.theme-slack-dna li:nth-child(4n + 1) svg {
  color: oklch(0.62 0.15 200);
}
.theme-slack-dna li:nth-child(4n + 2) svg {
  color: oklch(0.68 0.17 145);
}
.theme-slack-dna li:nth-child(4n + 3) svg {
  color: oklch(0.75 0.17 75);
}
.theme-slack-dna li:nth-child(4n + 4) svg {
  color: oklch(0.6 0.2 20);
}

/* signature */
.theme-slack-dna { --font-ui: var(--font-display); }
.theme-slack-dna h1 { font-weight: 800; letter-spacing: -0.03em; }
.theme-slack-dna h2 { border-image: linear-gradient(90deg, #36c5f0, #2eb67d, #ecb22e, #e01e5a) 1; border-bottom: 3px solid; padding-bottom: 0.4rem; }

/* alt mode: auto-derived dark variant */
.theme-slack-dna.alt-mode {
  --bg: oklch(0.145 0.002 300.0);
  --surface: oklch(0.185 0.002 300.0);
  --surface-2: oklch(0.225 0.002 300.0);
  --fg: oklch(0.97 0.005 90);
  --fg-muted: oklch(0.70 0.01 90);
  --line: oklch(1 0 0 / 14%);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --accent: oklch(0.62 0.108 327.1);
  --accent-fg: oklch(0.13 0 0);
}

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
